                $crate::__install_host(::std::boxed::Box::new(__OctraPluginHost));
                let config: $crate::__serde_json::Value = $crate::__serde_json::from_str(&config_json)
                    .map_err(|error| ::std::format!("invalid config: {error}"))?;
